-- Demo Kit uploads: let signed-in portal users upload the demo assets into documents/demo-assets/
-- (the portal's Settings → Demo assets uploader). Guarded so re-running is safe.
do $$
begin
  if exists (select 1 from information_schema.tables where table_schema='storage' and table_name='objects') then
    if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='demo_assets_upload_insert') then
      execute $p$create policy demo_assets_upload_insert on storage.objects for insert to authenticated
               with check (bucket_id = 'documents' and name like 'demo-assets/%')$p$;
    end if;
    if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='demo_assets_upload_update') then
      execute $p$create policy demo_assets_upload_update on storage.objects for update to authenticated
               using (bucket_id = 'documents' and name like 'demo-assets/%')
               with check (bucket_id = 'documents' and name like 'demo-assets/%')$p$;
    end if;
  end if;
end $$;
